        DataStream<Tuple2<Long, Integer>> result = maxSessionPerJob
                .connect(broadcastFinishedJobs)
                .process(new KeyedBroadcastProcessFunction<Long, Tuple2<Long, Integer>, Long, Tuple2<Long, Integer>>() {

                    private final MapStateDescriptor<Long, Boolean> finishedJobsDesc =
                            new MapStateDescriptor<>("finishedJobs", BasicTypeInfo.LONG_TYPE_INFO, BasicTypeInfo.BOOLEAN_TYPE_INFO);

                    private transient ValueState<Integer> maxCountState;
                    private transient ValueState<Boolean> emittedState;

                    @Override
                    public void open(Configuration parameters) {
                        maxCountState = getRuntimeContext().getState(
                                new ValueStateDescriptor<>("maxCount", Integer.class));
                        emittedState = getRuntimeContext().getState(
                                new ValueStateDescriptor<>("emitted", Boolean.class));
                    }

                    @Override
                    public void processElement(Tuple2<Long, Integer> value,
                                               ReadOnlyContext ctx,
                                               Collector<Tuple2<Long, Integer>> out) throws Exception {
                        // Update max session count for this job
                        Integer current = maxCountState.value();
                        if (current == null || value.f1 > current) {
                            maxCountState.update(value.f1);
                        }

                        // Check if job is finished
                        Boolean isFinished = ctx.getBroadcastState(finishedJobsDesc).get(value.f0);
                        if (isFinished != null && isFinished) {
                            Boolean emitted = emittedState.value();
                            if (emitted == null || !emitted) {
                                out.collect(new Tuple2<>(value.f0, maxCountState.value()));
